{
  "originalFormula": "E_{g} = 8 \, eV \, \\text{for} \, SiO_{2}",
  "genericFormula": "E_{g} = E_{g, \\text{material}}",
  "description": "Esta fórmula representa a energia de bandgap, que é a quantidade de energia necessária para mover um elétron de uma banda de energia para outra em um material semicondutor, especificamente no caso do dióxido de silício (SiO2).",
  "concepts": [
    "Energia de bandgap",
    "Semicondutores",
    "Propriedades elétricas de materiais"
  ],
  "symbols": [
    {
      "symbol": "E_{g}",
      "description": "Representa a energia de bandgap, que é a energia mínima necessária para excitar um elétron de uma banda de valência para a banda de condução."
    },
    {
      "symbol": "eV",
      "description": "Representa o elétron-volt, que é uma unidade de medida de energia usada frequentemente em física, especialmente em contextos de semicondutores e partículas subatômicas."
    },
    {
      "symbol": "SiO_{2}",
      "description": "Representa o dióxido de silício, um material semicondutor amplamente utilizado em eletrônica e optoeletrônica."
    }
  ]
}

{
  "originalFormula": "E_{g} = 1.12 \, eV \, \\text{at} \, T = 300K",
  "genericFormula": "E_{g} = E_{g,0} \, \\text{at} \, T = T_{0}",
  "description": "Esta fórmula representa a energia de bandgap de um material semicondutor, que é a quantidade mínima de energia necessária para mover um elétron da banda de valência para a banda de condução. A energia de bandgap é uma característica fundamental que determina as propriedades eletrônicas e ópticas do semicondutor.",
  "concepts": [
    "Energia de bandgap",
    "Semicondutores",
    "Temperatura",
    "Propriedades eletrônicas"
  ],
  "symbols": [
    {
      "symbol": "E_{g}",
      "description": "Representa a energia de bandgap do semicondutor, que é a diferença de energia entre a banda de valência e a banda de condução."
    },
    {
      "symbol": "eV",
      "description": "Representa electronvolt, uma unidade de medida de energia comumente utilizada em física de semicondutores, onde 1 eV é a energia adquirida por um elétron ao passar por uma diferença de potencial de 1 volt."
    },
    {
      "symbol": "T",
      "description": "Representa a temperatura em Kelvin, que é uma medida da energia térmica das partículas em um sistema. A temperatura pode afetar a energia de bandgap de um material."
    },
    {
      "symbol": "T_{0}",
      "description": "Representa uma temperatura de referência, que neste caso é 300 Kelvin, uma temperatura comum para medições em física de semicondutores."
    },
    {
      "symbol": "E_{g,0}",
      "description": "Representa a energia de bandgap em uma temperatura de referência, que é a energia de bandgap medida a 300 Kelvin."
    }
  ]
}

{
  "originalFormula": "E = h u",
  "genericFormula": "E = h \cdot \nu",
  "description": "Esta fórmula relaciona a energia de uma onda eletromagnética com sua frequência. A energia é diretamente proporcional à frequência da onda, onde a constante de proporcionalidade é a constante de Planck.",
  "concepts": ["energia", "frequência", "ondas eletromagnéticas", "constante de Planck"],
  "symbols": [
    {
      "symbol": "E",
      "description": "Representa a energia da onda eletromagnética, que é a capacidade de realizar trabalho ou causar mudanças em um sistema."
    },
    {
      "symbol": "h",
      "description": "É a constante de Planck, uma constante fundamental na física que relaciona a energia de um fóton à sua frequência. Seu valor é aproximadamente 6.626 x 10^-34 Joule segundo."
    },
    {
      "symbol": "ν",
      "description": "Representa a frequência da onda eletromagnética, que é o número de ciclos que ocorrem em um segundo. É medida em Hertz (Hz)."
    }
  ]
}
